import React from 'react';

import type { AudioNode } from './../../ricos-schema/next-schema/index.js';

import { getAudioSrc } from '../consts.js';
import { ROOT } from '../data-hooks.js';
import styles from '../statics/styles/audio-scss.js';
import type { AudioPluginViewerConfig } from '../types.js';
import AudioEmbedViewer from './audio-embed-viewer.js';
import { ReactPlayerWrapper } from './react-player-wrapper.js';

interface Props {
  node: AudioNode;
  settings: AudioPluginViewerConfig;
  disabled?: boolean;
  isLoading?: boolean;
  updateAttributes?: (args: $TSFixMe) => void;
}

const AudioViewer: React.FC<Props> = ({
  node,
  settings,
  disabled,
  isLoading,
  updateAttributes,
}) => {
  const { audio, authorName, name, coverImage, disableDownload, html } = node.audioData || {};
  const url = getAudioSrc(audio?.src, settings as any);
  const shouldEmbed = !!html;
  const saveDurationToData = (duration: $TSFixMe) =>
    updateAttributes?.({ audio: { ...audio, duration } });

  return (
    <div className={styles.container} data-hook={ROOT}>
      {!shouldEmbed ? (
        <ReactPlayerWrapper
          url={url}
          name={name}
          authorName={authorName}
          coverImage={{ src: coverImage?.src.id }}
          disableDownload={disableDownload}
          helpers={{}}
          disabled={disabled}
          isLoading={isLoading}
          saveDurationToData={saveDurationToData}
          initialDuration={audio?.duration}
        />
      ) : (
        <AudioEmbedViewer node={node} settings={settings as any} />
      )}
    </div>
  );
};

export default AudioViewer;
