import { definePmNodeConverter } from './../../pm-converters/types.js';
import { removeNullValues } from './../../pm-converters/utils.js';
import type { AudioNode } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';
import type { PmAudioNode } from './../../_shared/pm-node-types.js';

export const audioConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.AUDIO],
    convert: (node): PmAudioNode => {
      const { id = '', audioData } = node || {};

      return {
        type: Node_Type.AUDIO,
        attrs: {
          id,
          containerData: audioData?.containerData ?? null,
          audio: audioData?.audio ?? null,
          disableDownload: audioData?.disableDownload ?? null,
          coverImage: audioData?.coverImage ?? null,
          name: audioData?.name ?? null,
          authorName: audioData?.authorName ?? null,
          html: audioData?.html ?? null,
          animation: audioData?.animation ?? null,
        },
      };
    },
  },
  fromPm: {
    types: [Node_Type.AUDIO],
    convert: node => {
      const attributes = (node as PmAudioNode).attrs || {};
      const { id, ...data } = attributes;
      const { loading, error, ...filteredData } = removeNullValues(data);

      if (loading || error) {
        return undefined;
      }

      const result: AudioNode = {
        type: Node_Type.AUDIO,
        id,
        nodes: [],
        audioData: filteredData,
      };
      return result;
    },
  },
});
