import React from 'react';

import type { PluginProps } from './../../ricos-types/index.js';
import type { PmAudioNode } from './../../_shared/pm-node-types.js';
import type { AudioPluginViewerConfig } from './../types.js';

import { fromPmAudioAnyState } from '../converters/from-pm-audio-any-state.js';
import AudioViewer from '../viewer/audio-viewer.js';

export const Audio: React.FC<PluginProps> = ({ settings, node, updateAttributes }) => {
  const { loading } = node.attrs;

  const ricosNode = fromPmAudioAnyState(node as unknown as PmAudioNode);

  return (
    <AudioViewer
      node={ricosNode}
      updateAttributes={updateAttributes}
      settings={settings as AudioPluginViewerConfig}
      isLoading={loading}
    />
  );
};
