import React from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { FocusManager } from './../../_shared/focus-manager/focus-manager.js';

import styles from '../statics/styles/audio-scss.js';
import type { audioMenuDataType } from '../types.js';

interface Props {
  options: audioMenuDataType;
  onClose: () => void;
  dataHook?: string;
}

const optionElement = (option: audioMenuDataType[0]) => {
  const selected = option?.selected;
  const content = option.icon ? (
    <span className={styles.dropdownContentWithIcon}>
      {option.icon()}
      {option.text}
    </span>
  ) : (
    <span className={styles.dropdownContent}>{option.text}</span>
  );
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      option.onClick();
    }
  };

  return (
    <button
      key={option.text}
      className={selected ? styles.dropdownSelectedButton : ''}
      onKeyDown={onKeyDown}
      onClick={option.onClick}
      data-hook={option?.dataHook}
      type="button"
    >
      {content}
    </button>
  );
};

export const DropdownMenu: React.FC<Props> = ({ options, onClose, dataHook }) => {
  const { jsdomMode } = React.useContext(RicosContext);
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onClose();
    }
  };
  return (
    <FocusManager onKeyDown={onKeyDown} jsdomMode={jsdomMode}>
      <div className={styles.dropdownMenuWrapper} role="menu" data-hook={dataHook}>
        {options.map(option => optionElement(option))}
      </div>
    </FocusManager>
  );
};
