import { fromFile } from './../bundled-dependencies/id3js.js';
import type {
  AudioComponentData,
  ImageComponentData,
  UpdateEntityFileSelectFunc,
  UpdateEntityFileUploadFunc,
} from './../ricos-content/index.js';
import type { PluginServices } from './../ricos-plugins/editor-plugins.js';
import type { PublicCommands, RicosServices } from './../ricos-types/index.js';
import { getUploadError } from './../_shared/get-upload-error.js';
import { logInvariant } from './../_shared/log-invariant.js';
import { createOpenMediaManagerFn } from './../_shared/media-manager/create-open-media-manager-fn.js';
import { MediaManagerMediaType } from './../_shared/media-manager/types.js';
import type { PickMediaFn } from './../_shared/media/pick-media.js';
import type {
  PickMediaAudioData,
  PickMediaImageData,
  PublicPickMedia,
} from './../_shared/media/public-pick-media.js';
import type { PmAudioNode } from './../_shared/pm-node-types.js';
import { MediaType } from './../_shared/request-service-provider/consts.js';
import { createUploadFn } from './../_shared/request-service-provider/media-manager-uploader.js';
import type {
  MediaManagerSDKError,
  RawAudioData,
  RawImageData,
} from './../_shared/request-service-provider/upload-types.js';
import { upload } from './../_shared/upload/upload.js';
import { withFileSizeLimitation } from './../_shared/with-file-size-limitation.js';
import { audioFileTypes } from './/consts.js';
import { RICOS_DEFAULTS } from './/defaults.js';

import { AUDIO_TYPE } from './types.js';

const getAudioPickMedia = ({
  services,
  type,
  handleFileUpload,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  handleFileUpload: ReturnType<typeof createHandleFileUploadFn>;
  type: 'audio' | 'image';
}): PickMediaFn | PublicPickMedia['pickAudio'] | PublicPickMedia['pickImage'] => {
  const devPickMedia = services.devService().pickMedia;
  const editorPickMedia =
    type === 'audio'
      ? services.editorProps.pickMedia?.pickAudio
      : services.editorProps.pickMedia?.pickImage;
  const handleFileSelection =
    services.devService().handleFileSelection ?? createHandleFileSelectionFn(services);

  return devPickMedia
    ? devPickMedia
    : editorPickMedia
      ? editorPickMedia
      : handleFileSelection
        ? async () => {
            try {
              const data = await new Promise<AudioComponentData | ImageComponentData>(
                (resolve, reject) =>
                  handleFileSelection(
                    ({ data }) => resolve(data),
                    { isCoverImage: type === 'image' },
                    reject
                  )
              );
              return { type: 'ready-media' as const, media: [data] };
            } catch {
              return { type: 'cancel' as const };
            }
          }
        : async ({ mimeType }: Parameters<PickMediaFn>[0]) => {
            const files =
              (await services.uploadService?.selectFiles({ accept: mimeType, multiple: false })) ??
              [];
            return { type: 'file' as const, file: files, customUploadFn: handleFileUpload };
          };
};

type GetAudioAttributesProps =
  | {
      type: 'audio';
      componentData: PmAudioNode['attrs'];
      uploadData: PmAudioNode['attrs'] | PickMediaAudioData;
    }
  | {
      type: 'image';
      componentData: PmAudioNode['attrs'];
      uploadData: ImageComponentData | PickMediaImageData;
    };

const isPickMediaAudioType = (
  data: PmAudioNode['attrs'] | PickMediaAudioData
): data is PickMediaAudioData => 'type' in data && data.type === 'audio';

const isPickMediaImageType = (
  data: ImageComponentData | PickMediaImageData
): data is PickMediaImageData => 'type' in data && data.type === 'image';

const getAudioAttributes = ({ type, uploadData, componentData }: GetAudioAttributesProps) => {
  if (type === 'audio') {
    if (isPickMediaAudioType(uploadData)) {
      return {
        ...componentData,
        audio: { src: uploadData.src },
        name: uploadData.title ?? componentData.name ?? '',
        authorName: uploadData.authorName ?? componentData?.authorName ?? '',
        html: null,
        tempData: undefined,
        loading: undefined,
      } satisfies PmAudioNode['attrs'];
    }

    return {
      ...componentData,
      audio: uploadData?.audio ?? componentData?.audio ?? null,
      name: uploadData?.name ?? componentData?.name ?? '',
      authorName: uploadData?.authorName ?? componentData?.authorName ?? '',
      html: null,
      tempData: undefined,
      loading: undefined,
    } satisfies PmAudioNode['attrs'];
  }

  if (isPickMediaImageType(uploadData)) {
    return {
      ...componentData,
      coverImage: {
        src: uploadData.src,
        width: uploadData.width,
        height: uploadData.height,
      },
      tempData: undefined,
      loading: undefined,
    } satisfies PmAudioNode['attrs'];
  }

  return {
    ...componentData,
    coverImage: {
      src: { id: uploadData.file_name },
      width: uploadData.width,
      height: uploadData.height,
    },
    tempData: undefined,
    loading: undefined,
  } satisfies PmAudioNode['attrs'];
};

export const handleAudioUpload = async ({
  services,
  publicCommands,
  nodeId,
  type,
  referenceElement,
}: {
  services: Pick<
    RicosServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  publicCommands: PublicCommands;
  nodeId?: string;
  type: 'audio' | 'image';
  referenceElement?: HTMLElement;
}) => {
  const mimeType = type === 'audio' ? audioFileTypes : 'image/*';
  const handleFileUpload = createHandleFileUploadFn(services);
  const pickMedia = getAudioPickMedia({ services, type, handleFileUpload });

  const result = await pickMedia({ mimeType, multiple: false });

  switch (result.type) {
    case 'ready-media': {
      const id = nodeId || publicCommands.insertBlockWithBlankLines(AUDIO_TYPE, RICOS_DEFAULTS);
      setTimeout(() => {
        const componentData: PmAudioNode['attrs'] = publicCommands?.getBlockComponentData(id);
        const updatedData = getAudioAttributes(
          type === 'audio'
            ? {
                type: 'audio',
                componentData,
                uploadData: result.media[0] as PmAudioNode['attrs'] | PickMediaAudioData,
              }
            : {
                type: 'image',
                componentData,
                uploadData: result.media[0] as ImageComponentData | PickMediaImageData,
              }
        );

        publicCommands?.setBlock(id, AUDIO_TYPE, {
          ...updatedData,
          tempData: undefined,
          loading: undefined,
          error: undefined,
        });
      });
      return;
    }
    case 'file': {
      const file = result.file[0];
      if (file) {
        const tags = await getAudioTags(file);
        const targetNodeId =
          nodeId ||
          publicCommands.insertBlockWithBlankLines(AUDIO_TYPE, {
            ...RICOS_DEFAULTS,
            ...tags,
            loading: true,
          });

        const trackBi = services.uploadService?.trackUploadBi(AUDIO_TYPE, file.size, file.name);

        try {
          const url = URL.createObjectURL(file);
          await Promise.resolve();
          const componentData = publicCommands?.getBlockComponentData(targetNodeId);

          publicCommands?.setBlock(targetNodeId, AUDIO_TYPE, {
            ...componentData,
            name: componentData.name || file.name.split('.')[0],
            tempData: url,
            loading: true,
            error: null,
          });

          trackBi?.start();
          const uploadFn = result.customUploadFn || handleFileUpload;

          if (!uploadFn) {
            logInvariant(Error('No upload function provided'));
            throw new Error('No upload function provided');
          }

          const uploadedFile = await upload(uploadFn, file);

          const updatedData = getAudioAttributes({
            type,
            componentData: publicCommands?.getBlockComponentData(targetNodeId),
            uploadData: uploadedFile.data as any,
          });

          publicCommands?.setBlock(targetNodeId, AUDIO_TYPE, updatedData);

          URL.revokeObjectURL(url as string);
          trackBi?.success();
        } catch (error: any) {
          const componentData = publicCommands?.getBlockComponentData(targetNodeId);
          publicCommands?.setBlock(targetNodeId, AUDIO_TYPE, {
            ...componentData,
            error,
            loading: null,
          });

          trackBi?.error(error);
          services.uploadService?.notifyError(error);
        }
      } else {
        console.error('No file selected');
      }
      return;
    }
    case 'cancel': {
      services.modals.notifyExternalModalClosed({ focusReturnElement: referenceElement });
      return;
    }
    default: {
      console.error('Unhandeled media picker result:', result);
      return;
    }
  }
};

const getAudioTags = async (file: File) => {
  try {
    const tags = await fromFile(file);
    return { name: tags?.title, authorName: tags?.artist };
  } catch (error) {
    console.error(error);
    return {};
  }
};

export const createHandleFileUploadFn = (
  services: Pick<PluginServices, 'wixInstance' | 'editorProps'>
) => {
  const { metaSiteId, uid, siteOwnerId } = services.wixInstance();

  if (!metaSiteId) {
    return undefined;
  }

  const audioUpload = (
    file: File,
    updateEntity: UpdateEntityFileUploadFunc<AudioComponentData | ImageComponentData>
  ) => {
    const upload = createUploadFn(services);
    const isCoverImage = file.type.includes('image');
    const mediaType = isCoverImage ? MediaType.IMAGE : MediaType.AUDIO;
    return upload(file, mediaType)
      .then((res: RawAudioData | RawImageData) => {
        if (isCoverImage) {
          const { file_name, original_file_name, height, width } = res as RawImageData;
          return updateEntity({
            data: {
              id: file_name,
              height,
              width,
              original_file_name,
              file_name,
            },
          });
        } else {
          const {
            file_output: { audio },
          } = res as RawAudioData;
          updateEntity({
            data: {
              audio: { src: { id: audio[0].url } },
            },
          });
        }
      })
      .catch((error: MediaManagerSDKError) => {
        const isOwner = siteOwnerId === uid;
        const mediaUploadError = getUploadError(error, metaSiteId, isOwner);
        updateEntity({ error: mediaUploadError });
      });
  };

  return withFileSizeLimitation(audioUpload, services.editorProps.fileUploadSizeLimit);
};

const createHandleFileSelectionFn = (services: Pick<PluginServices, 'wixInstance' | 'modals'>) => {
  const openMediaManager = createOpenMediaManagerFn(services.modals);
  if (!openMediaManager) {
    return undefined;
  }

  const audioUpload = (
    updateEntity: UpdateEntityFileSelectFunc<AudioComponentData | ImageComponentData>,
    options: { isCoverImage: boolean },
    onCancel: () => void
  ) => {
    if (options.isCoverImage) {
      return openMediaManager({
        mediaType: MediaManagerMediaType.IMAGE,
        appDefId: services.wixInstance().appDefId,
      })
        .then(items => {
          const file = items[0];
          const { uri, width, height, title } = file;
          updateEntity({
            data: { id: uri, file_name: uri, original_file_name: title, width, height },
          });
        })
        .catch(onCancel);
    }

    return openMediaManager({
      mediaType: MediaManagerMediaType.AUDIO,
      appDefId: services.wixInstance().appDefId,
    })
      .then(items => {
        const file = items[0];
        const { audio } = file.fileOutput;
        const name = file.title.split('.')[0];
        updateEntity({
          data: { audio: { src: { id: audio[0].url } }, name },
        });
      })
      .catch(onCancel);
  };

  return audioUpload;
};
