import { Box, FormField, SegmentedToggle } from '@wix/design-system';
import { LinkSmall, UploadExportSmall } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { ModalServiceContext, PluginsEventsContext, RicosContext } from './../../ricos-context/index.js';
import type { AudioData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { MEDIA_POPOVERS_TABS_NAMES_BI } from './../../wix-rich-content-common/index.js';
import { Panel, PanelHeader } from './../../ui-components/index.js';

import { INSERT_AUDIO_MODAL, INSERT_AUDIO_MODAL_SOURCE_TOGGLE } from '../data-hooks.js';
import { AUDIO_TYPE } from '../types.js';
import { AudioEmbed } from './audio-embed.js';
import { AudioUpload } from './audio-upload.js';

export type InsertModalProps = {
  componentData: AudioData;
  nodeId?: string;
  embedType?: boolean;
  modalId: string;
};

const SourceOptionValue = {
  EMBED: 'embed',
  UPLOAD: 'upload',
} as const;

type SourceOption = (typeof SourceOptionValue)[keyof typeof SourceOptionValue];

export const InsertModal: FC<InsertModalProps> = ({
  nodeId,
  componentData,
  embedType,
  modalId,
}) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext) || {};
  const pluginsEvents = useContext(PluginsEventsContext);
  const logBi = useBiNext({ pluginId: 'audio', modalId, nodeId });

  const [selectedSource, setSelectedSource] = useState<SourceOption>(
    embedType || componentData?.audio?.src?.url ? 'embed' : 'upload'
  );

  const onSourceToggleClick = (_: React.SyntheticEvent, value: string) => {
    selectedSource !== value &&
      pluginsEvents.publishPluginPopoverTabSwitch?.({
        pluginId: AUDIO_TYPE,
        buttonName: MEDIA_POPOVERS_TABS_NAMES_BI[value.toLowerCase() as SourceOption],
      });

    setSelectedSource(value as SourceOption);
    logBi({ dataHook: INSERT_AUDIO_MODAL_SOURCE_TOGGLE, value });
  };

  const closeModal = () => modalService.closeModal(modalId);

  return (
    <Panel
      closeButtonProps={{ onClick: closeModal }}
      dataHook={INSERT_AUDIO_MODAL}
      height="fit-content"
    >
      <PanelHeader title={t('Audio_Modal_Header_Title')} />

      <Box direction="vertical" padding="SP3" gap="SP3">
        <FormField label={t('Audio_Modal_Toggle_Source_Label')}>
          <SegmentedToggle
            defaultSelected={selectedSource}
            size="small"
            onClick={onSourceToggleClick}
            dataHook={INSERT_AUDIO_MODAL_SOURCE_TOGGLE}
          >
            <SegmentedToggle.Button value={SourceOptionValue.EMBED} prefixIcon={<LinkSmall />}>
              {t('MediaModal_Tabs_Embed')}
            </SegmentedToggle.Button>
            <SegmentedToggle.Button
              value={SourceOptionValue.UPLOAD}
              prefixIcon={<UploadExportSmall />}
            >
              {t('MediaModal_Tabs_Upload')}
            </SegmentedToggle.Button>
          </SegmentedToggle>
        </FormField>
        {selectedSource === 'embed' && (
          <AudioEmbed componentData={componentData} closeModal={closeModal} logBi={logBi} />
        )}
        {selectedSource === 'upload' && (
          <AudioUpload nodeId={nodeId} closeModal={closeModal} logBi={logBi} />
        )}
      </Box>
    </Panel>
  );
};
