export const downloadFile = (url: string, fileName: $TSFixMe) => {
  fetch(url, {
    method: 'GET',
  })
    .then(response => response.blob())
    .then(blob => {
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a); // we need to append the element to the dom -> otherwise it will not work in firefox
      a.click();
      a.remove(); //afterwards we remove the element again
    });
};

export const getAudioSrc = (src: $TSFixMe, config: AudioPluginEditorConfig) => {
  if (src?.url) {
    return src.url;
  }
  if (typeof src === 'object') {
    if (config && config.getAudioUrl) {
      return config.getAudioUrl(src);
    } else {
      console.error('must set getAudioUrl in plugin config when using custom audio source!', src); //oxlint-disable-line no-console
    }
  }
  return src;
};

