import React from 'react';

import classes from '../statics/styles/icon-button-scss.js';

type IconButtonProps = {
  isLoading?: boolean;
  icon: React.ReactNode;
} & React.HTMLAttributes<HTMLButtonElement> &
  React.PropsWithChildren;

export const IconButton: React.FC<IconButtonProps> = ({ children, isLoading, icon, ...props }) => {
  return (
    <div>
      <button className={classes.audioIconButton} type="button" disabled={isLoading} {...props}>
        {icon}
      </button>

      {children}
    </div>
  );
};
