import type { EditorPluginConfig, ViewerPluginConfig } from './../ricos-types/index.js';
export { AUDIO_TYPE } from './../ricos-content/index.js';

export type audioMenuDataType = {
  text: string;
  onClick: () => void;
  selected?: boolean;
  dataHook?: string;

  icon?: (props?: any) => JSX.Element;
}[];

export const audioButtonsTypes = {
  audio: 'audio',
  soundCloud: 'soundCloud',
  spotify: 'spotify',
} satisfies Record<string, AudioButton>;

type AudioButton = 'audio' | 'soundCloud' | 'spotify';

export interface AudioPluginEditorConfig extends EditorPluginConfig {
  type: 'audio';
  /**
   * Controls which audio source buttons appear in the toolbar insert menu.
   * By default, only the file-upload (`'audio'`) button is shown.
   * Add `'soundCloud'` and `'spotify'` to enable embedding from those services.
   * @defaultValue `['audio']`
   */
  exposeButtons?: AudioButton[];
  /**
   * When `true`, disables the download button on newly inserted audio blocks.
   * @defaultValue true
   */
  disableDownload?: boolean;
  /**
   * Resolves an audio file ID to a full playback URL.
   * Called when rendering audio nodes that store a relative source (e.g. Wix Media).
   * If not provided, a default Wix Media resolver is used.
   */
  getAudioUrl?: (src: { id: string }) => string;
}

export interface AudioPluginViewerConfig extends ViewerPluginConfig {
  /**
   * Resolves an audio file ID to a full playback URL.
   * Called when rendering audio nodes that store a relative source (e.g. Wix Media).
   * If not provided, a default Wix Media resolver is used.
   */
  getAudioUrl?: (src: { id: string }) => string;
}
