import { PauseFilledSmall, PlayFilledSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { Helpers } from './../../ricos-types/index.js';
import { DoubleLoader } from './../../ui-components/Components/double-loader.js';

import { AUDIO_ACTION_NAMES, AUDIO_BI_VALUES } from '../consts.js';
import styles from '../statics/styles/audio-scss.js';
import { AUDIO_TYPE } from '../types.js';

interface Props {
  handlePause: () => void;
  handlePlay: () => void;
  isPlaying: boolean;
  disabled?: boolean;
  isLoading?: boolean;
  helpers?: Helpers;
}

export const AudioActionIcons: React.FC<Props> = ({
  isPlaying,
  handlePause,
  handlePlay,
  disabled,
  isLoading,
  helpers,
}) => {
  const { tabIndex } = useContext(RicosContext);

  const onClick = () => {
    const ACTION_BI_VALUE = isPlaying ? AUDIO_BI_VALUES.PAUSE : AUDIO_BI_VALUES.PLAY;
    helpers?.onViewerAction?.(AUDIO_TYPE, AUDIO_ACTION_NAMES.playAudio, ACTION_BI_VALUE);
    isPlaying ? handlePause() : handlePlay();
  };

  const onKeyDown = (e: $TSFixMe) => {
    if (e.key === 'Enter') {
      onClick();
    }
  };

  const ComponentIcon = disabled || !isPlaying ? PlayFilledSmall : PauseFilledSmall;
  const ariaLabel = isPlaying ? 'pause' : 'play';

  return isLoading ? (
    <span className={styles.audioLoader}>
      <DoubleLoader />
    </span>
  ) : (
    <button
      type="button"
      className={styles.playPauseButton}
      onClick={onClick}
      onKeyDown={onKeyDown}
      aria-label={ariaLabel}
      tabIndex={tabIndex}
    >
      <ComponentIcon />
    </button>
  );
};
